<?php
require __DIR__.'/bootstrap-loader.php';
$login_error=''; $config=admin_config();
if ($_SERVER['REQUEST_METHOD']==='POST') {
    if (!valid_csrf()) { http_response_code(403); exit('Обновите страницу: срок действия формы истёк.'); }
    $action=text_input($_POST,'action',20);
    if ($action==='logout') { $_SESSION=[]; session_regenerate_id(true); header('Location: admin.php'); exit; }
    if ($action==='login' && $config) {
        $address=address_key(); $now=time();
        db()->prepare('DELETE FROM login_attempts WHERE created_at<?')->execute([$now-900]);
        $attempts=db()->prepare('SELECT COUNT(*) FROM login_attempts WHERE address=? AND created_at>?'); $attempts->execute([$address,$now-900]);
        if ($attempts->fetchColumn()>=5) { http_response_code(429); $login_error='Слишком много попыток. Попробуйте через 15 минут.'; }
        else {
            $username=text_input($_POST,'username',60); $password=$_POST['password']??'';
            if (is_string($password) && hash_equals($config['username'],$username) && password_verify($password,$config['password_hash'])) {
                session_regenerate_id(true); $_SESSION['admin']=$username; $_SESSION['admin_signature']=hash('sha256',$config['password_hash']); $_SESSION['last_active']=time(); $_SESSION['csrf']=bin2hex(random_bytes(32));
                db()->prepare('DELETE FROM login_attempts WHERE address=?')->execute([$address]);
                header('Location: admin.php'); exit;
            }
            db()->prepare('INSERT INTO login_attempts VALUES(?,?)')->execute([$address,$now]);
            $login_error='Неверный логин или пароль.';
        }
    }
}
$authorized=is_admin();
$period=(int)($_GET['period']??30); if (!in_array($period,[7,30,90],true)) $period=30;
$start=date('Y-m-d',strtotime('-'.($period-1).' days')); $end=date('Y-m-d');
if ($_SERVER['REQUEST_METHOD']==='POST' && $authorized) {
    if (($_POST['action']??'')==='status') {
        $status=text_input($_POST,'status',20); $id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);
        if ($id && in_array($status,['new','contacted','attended'],true)) db()->prepare('UPDATE leads SET status=? WHERE id=?')->execute([$status,$id]);
        header('Location: admin.php?period='.$period); exit;
    }
    if (($_POST['action']??'')==='export') {
        header('Content-Type: text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename="kazagrofarm-leads-'.date('Y-m-d').'.csv"');
        $output=fopen('php://output','w'); fwrite($output,"\xEF\xBB\xBF");
        fputcsv($output,['Дата','Имя','Фамилия','Телефон','Тип','Компания','Интерес','Источник','Канал','Кампания','Статус'],';', '"', '');
        $stmt=db()->prepare('SELECT * FROM leads WHERE day BETWEEN ? AND ? ORDER BY id DESC'); $stmt->execute([$start,$end]);
        foreach ($stmt as $row) {
            $values=[$row['created_at'],$row['first_name'],$row['last_name'],$row['phone'],$row['person_type']==='legal'?'Юрлицо':'Физлицо',$row['company'],$row['interest'],$row['source'],$row['medium'],$row['campaign'],$row['status']];
            $values=array_map(fn($v)=>preg_match('/^[\s]*[=+@-]/u',(string)$v)?"'".$v:$v,$values);
            fputcsv($output,$values,';','"','');
        }
        fclose($output); exit;
    }
}
function summary(?string $start=null,?string $end=null): array {
    $where=$start?' WHERE day BETWEEN ? AND ?':''; $params=$start?[$start,$end]:[];
    $v=db()->prepare('SELECT COUNT(DISTINCT visitor) unique_count,COALESCE(SUM(views),0) views,COALESCE(SUM(started),0) starts FROM visitors'.$where); $v->execute($params); $row=$v->fetch();
    $l=db()->prepare('SELECT COUNT(*) FROM leads'.$where); $l->execute($params); $row['leads']=(int)$l->fetchColumn();
    $r=db()->prepare('SELECT COUNT(*) FROM route_clicks'.$where); $r->execute($params); $row['route_clicks']=(int)$r->fetchColumn();
    $row['conversion']=$row['unique_count']?round($row['leads']/$row['unique_count']*100,1):0;
    return $row;
}
if ($authorized) {
    $overall=summary(); $selected=summary($start,$end);
    $v=db()->prepare('SELECT day,COUNT(*) visitors,SUM(views) views,SUM(started) starts FROM visitors WHERE day BETWEEN ? AND ? GROUP BY day'); $v->execute([$start,$end]); $visits=array_column($v->fetchAll(),null,'day');
    $l=db()->prepare('SELECT day,COUNT(*) leads FROM leads WHERE day BETWEEN ? AND ? GROUP BY day'); $l->execute([$start,$end]); $daily_leads=array_column($l->fetchAll(),null,'day');
    $r=db()->prepare('SELECT day,COUNT(*) clicks FROM route_clicks WHERE day BETWEEN ? AND ? GROUP BY day'); $r->execute([$start,$end]); $daily_routes=array_column($r->fetchAll(),null,'day');
    $daily=[]; for($i=0;$i<$period;$i++){ $day=date('Y-m-d',strtotime($start.' +'.$i.' days')); $daily[]=['day'=>$day,'visitors'=>(int)($visits[$day]['visitors']??0),'views'=>(int)($visits[$day]['views']??0),'starts'=>(int)($visits[$day]['starts']??0),'leads'=>(int)($daily_leads[$day]['leads']??0),'route_clicks'=>(int)($daily_routes[$day]['clicks']??0)]; }
    $maximum=max(1,...array_column($daily,'visitors'),...array_column($daily,'leads'));
    $page=max(1,(int)($_GET['page']??1)); $pages=max(1,(int)ceil($selected['leads']/25)); $page=min($page,$pages);
    $stmt=db()->prepare('SELECT * FROM leads WHERE day BETWEEN ? AND ? ORDER BY id DESC LIMIT 25 OFFSET ?'); $stmt->bindValue(1,$start); $stmt->bindValue(2,$end); $stmt->bindValue(3,($page-1)*25,PDO::PARAM_INT); $stmt->execute(); $leads=$stmt->fetchAll();
    $campaign_stmt=db()->prepare('SELECT source,campaign,COUNT(*) total FROM leads WHERE day BETWEEN ? AND ? GROUP BY source,campaign ORDER BY total DESC LIMIT 20'); $campaign_stmt->execute([$start,$end]); $campaigns=$campaign_stmt->fetchAll();
}
?><!DOCTYPE html><html lang="ru"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Кабинет — KazAgroFarm</title><link rel="stylesheet" href="assets/event.css"><link rel="stylesheet" href="assets/admin.css?v=route-1"></head><body class="admin-body">
