<?php else: ?><header class="admin-header"><div><a class="atm-logo" href="./"><strong>АТМ</strong></a><span>KazAgroFarm <b>/ Кабинет</b></span></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="logout"><button class="logout">Выйти →</button></form></header><main class="admin-main"><div class="dashboard-title"><div><span class="eyebrow">КАМПАНИЯ В ЦИФРАХ</span><h1>Встречи начинаются здесь.</h1><p>Посещения и записи на стенд C6 · часовой пояс Asia/Qyzylorda (UTC+5)</p></div><a class="admin-site-link" href="./" target="_blank" rel="noopener">Открыть лендинг →</a></div><h2 class="admin-section-title">За всё время</h2><div class="metric-grid"><?php foreach([['Уникальные посетители',$overall['unique_count'],'По анонимному cookie'],['Просмотры страницы',$overall['views'],'Повторные открытия учитываются'],['Регистрации',$overall['leads'],'Без дублей по телефону'],['Конверсия',$overall['conversion'].'%','Регистрации / посетители'],['Проложить маршрут',$overall['route_clicks'],'Всего нажатий на кнопки 2ГИС']] as [$label,$number,$note]): ?><article><span><?= e($label) ?></span><strong><?= e($number) ?></strong><small><?= e($note) ?></small></article><?php endforeach ?></div><section class="dashboard-panel"><div class="panel-heading"><div><h2>Динамика по дням</h2><p><?= e(date('d.m.Y',strtotime($start))) ?> — <?= e(date('d.m.Y',strtotime($end))) ?></p></div><div class="period-switch"><?php foreach([7,30,90] as $days): ?><a class="<?= $period===$days?'active':'' ?>" href="?period=<?= $days ?>"><?= $days ?> дней</a><?php endforeach ?></div></div><div class="period-summary"><span><b><?= e($selected['unique_count']) ?></b> посетителей</span><span><b><?= e($selected['starts']) ?></b> начали форму*</span><span><b><?= e($selected['leads']) ?></b> зарегистрировались</span><span><b><?= e($selected['conversion']) ?>%</b> конверсия</span><span class="route-period"><b><?= e($selected['route_clicks']) ?></b> нажатий «Проложить маршрут»</span></div><div class="chart-legend"><span><i></i> Посетители</span><span><i></i> Регистрации</span></div><div class="chart-scroll"><div class="daily-chart" style="--days:<?= $period ?>"><?php foreach($daily as $i=>$row): ?><div class="chart-day" title="<?= e($row['day']) ?>: <?= $row['visitors'] ?> посетителей, <?= $row['leads'] ?> заявок"><div class="bars"><div class="bar visits" style="height:<?= $row['visitors']/$maximum*100 ?>%"></div><div class="bar registrations" style="height:<?= $row['leads']/$maximum*100 ?>%"></div></div><span><?= e(date('d.m',strtotime($row['day']))) ?></span></div><?php endforeach ?></div></div><details class="daily-details"><summary>Точные значения по дням</summary><div class="table-scroll"><table><thead><tr><th>День</th><th>Посетители</th><th>Просмотры</th><th>Начали форму*</th><th>Регистрации</th><th>Маршрут: нажатия</th><th>Конверсия</th></tr></thead><tbody><?php foreach(array_reverse($daily) as $row): ?><tr><td><?= e(date('d.m.Y',strtotime($row['day']))) ?></td><td><?= $row['visitors'] ?></td><td><?= $row['views'] ?></td><td><?= $row['starts'] ?></td><td><?= $row['leads'] ?></td><td class="daily-route-clicks"><?= $row['route_clicks'] ?></td><td><?= $row['visitors']?round($row['leads']/$row['visitors']*100,1):0 ?>%</td></tr><?php endforeach ?></tbody></table></div></details><p class="analytics-note">Посетитель определяется cookie: другой браузер или очистка cookie создаёт нового посетителя. По дням один человек может учитываться повторно; общий показатель уникален за весь выбранный период. *Начало формы — первый ввод за день. Известные роботы исключаются, полная фильтрация ботов не гарантируется. «Проложить маршрут» — все нажатия на обе кнопки 2ГИС, включая повторные. Счётчик работает с момента обновления, нажатие не подтверждает поездку.</p></section><section class="dashboard-panel"><div class="panel-heading"><div><h2>Записи на встречу</h2><p><?= $selected['leads'] ?> заявок за выбранный период</p></div><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="export"><button class="export-button">Скачать CSV ↓</button></form></div><?php if (!$leads): ?><div class="admin-empty"><span>◎</span><h3>Первые встречи ещё впереди.</h3><p>Новые записи появятся здесь сразу после отправки формы.</p></div><?php else: ?><div class="table-scroll"><table class="leads-table"><thead><tr><th>Дата</th><th>Посетитель</th><th>Контакты / компания</th><th>Интерес</th><th>Кампания</th><th>Статус</th></tr></thead><tbody><?php foreach($leads as $lead): ?><tr><td><b><?= e(date('d.m',strtotime($lead['created_at']))) ?></b><small><?= e(date('H:i',strtotime($lead['created_at']))) ?></small></td><td><b><?= e($lead['first_name'].' '.$lead['last_name']) ?></b><small><?= $lead['person_type']==='legal'?'Юридическое лицо':'Физическое лицо' ?></small></td><td><a href="tel:<?= e($lead['phone']) ?>"><?= e($lead['phone']) ?></a><small><?= e($lead['company']?:'—') ?></small></td><td><?= e($lead['interest']?:'Не указано') ?></td><td><b><?= e($lead['source']?:'Прямой переход') ?></b><small><?= e($lead['campaign']?:'Без UTM-кампании') ?></small></td><td><form method="post" class="status-form"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= (int)$lead['id'] ?>"><select name="status" aria-label="Статус заявки <?= (int)$lead['id'] ?>"><?php foreach(['new'=>'Новая','contacted'=>'Связались','attended'=>'Пришёл'] as $value=>$label): ?><option value="<?= $value ?>" <?= $lead['status']===$value?'selected':'' ?>><?= $label ?></option><?php endforeach ?></select><button aria-label="Сохранить статус">✓</button></form></td></tr><?php endforeach ?></tbody></table></div><div class="pagination"><span>Страница <?= $page ?> из <?= $pages ?></span><div><?php if ($page>1): ?><a href="?period=<?= $period ?>&amp;page=<?= $page-1 ?>">← Назад</a><?php endif ?><?php if ($page<$pages): ?><a href="?period=<?= $period ?>&amp;page=<?= $page+1 ?>">Далее →</a><?php endif ?></div></div><?php endif ?></section><section class="dashboard-panel campaign-panel"><div><h2>Откуда приходят заявки</h2><p>Источники и кампании по UTM-меткам за выбранный период.</p><small>Пример ссылки для рекламы:<br><code>?utm_source=instagram&amp;utm_medium=paid&amp;utm_campaign=kazagrofarm</code></small></div><div><?php if (!$campaigns): ?><p class="analytics-note">Источник появится после первой регистрации.</p><?php else: ?><?php foreach($campaigns as $campaign): ?><div class="campaign-row"><span><b><?= e($campaign['source']?:'Прямой переход') ?></b><small><?= e($campaign['campaign']?:'Без кампании') ?></small></span><strong><?= (int)$campaign['total'] ?></strong></div><?php endforeach ?><?php endif ?></div></section><footer class="admin-footer">Данные заявок доступны только после входа. Не передавайте доступ к кабинету третьим лицам.</footer></main><?php endif ?></body></html>
